def isScramble(S1: str, S2: str) -> bool:
    def isScrambleHelper(s1, s2):
        if s1 == s2:
            return True
        if sorted(s1) != sorted(s2):
            return False
        n = len(s1)
        for i in range(1, n):
            if isScrambleHelper(s1[:i], s2[:i]) and isScrambleHelper(s1[i:], s2[i:]):
                return True
            if isScrambleHelper(s1[:i], s2[-i:]) and isScrambleHelper(s1[i:], s2[:-i]):
                return True
        return False

    return isScrambleHelper(S1, S2)
